def tbl(data,cw,hdr=True):
    t=Table(data,colWidths=[c*inch for c in cw]); st=[('FONT',(0,0),(-1,-1),'Helvetica',8.6),('ALIGN',(1,0),(-1,-1),'RIGHT'),('LINEBELOW',(0,0),(-1,0),0.8,NAVY),('LINEBELOW',(0,-1),(-1,-1),0.8,NAVY),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f3f5f8')]),('TOPPADDING',(0,0),(-1,-1),3),('BOTTOMPADDING',(0,0),(-1,-1),3)]
    if hdr: st.append(('FONT',(0,0),(-1,0),'Helvetica-Bold',8.6))
    t.setStyle(TableStyle(st)); return t
